70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
77	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
78	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
79	     */
80	    private static final Pattern EMAIL_PATTERN =
81	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
82	
83	    /**
84	     * Disposable email domains that are refused on create. An email whose domain (the part after the
85	     * {@code @}, compared case-insensitively) is in this set is rejected with a 400, since such
86	     * addresses are throwaway and unsuitable for contacting an owner.
87	     */
88	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
89	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
90	
91	    /**
92	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
93	     * memberId, the registrationDate and the membershipLevel is emitted through this logger.
94	     */
95	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
96	
97	    /**
98	     * Monotonically increasing sequence number stamped on each {@link OwnerCreatedEvent}, shared
99	     * across every create in this process so consumers can totally order the emitted events.
100	     */
101	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_SEQ =
102	        new java.util.concurrent.atomic.AtomicLong();
103	
104	    /**
105	     * Immutable structured audit event emitted through {@link #AUDIT} on a successful owner create.
106	     * <p>The identifier it carries is the owner's <em>current</em> primary identifier — its unified
107	     * {@code memberId} — so a downstream consumer always reads the live primary key from the one
108	     * {@code memberId} field. See {@link #primaryIdentifier(Owner)}.
109	     */
110	    private record OwnerCreatedEvent(long seq, Integer ownerId, String identifier, Integer membershipLevel) {
111	
112	        String toJson() {
113	            return "{\"seq\":" + seq
114	                + ",\"ownerId\":" + ownerId
115	                + ",\"memberId\":" + jsonString(identifier)
116	                + ",\"membershipLevel\":" + membershipLevel
117	                + ",\"event\":\"OWNER_CREATED\"}";
118	        }
119	
120	        private static String jsonString(String s) {
121	            if (s == null) {
122	                return "null";
123	            }
124	            StringBuilder sb = new StringBuilder(s.length() + 2).append('"');
125	            for (int i = 0; i < s.length(); i++) {
126	                char c = s.charAt(i);
127	                switch (c) {
128	                    case '"' -> sb.append("\\\"");
129	                    case '\\' -> sb.append("\\\\");
130	                    case '\n' -> sb.append("\\n");
131	                    case '\r' -> sb.append("\\r");
132	                    case '\t' -> sb.append("\\t");
133	                    default -> sb.append(c);
134	                }
135	            }
136	            return sb.append('"').toString();
137	        }
138	    }
139	
140	    /**
141	     * Remembers the owner created for each {@code Idempotency-Key} seen on a create, so a repeated
142	     * create carrying a key already in this map returns the originally created owner (200) instead of
143	     * creating a duplicate. Keys are supplied by the caller and are process-wide.
144	     */
145	    private final java.util.Map<String, Integer> idempotencyKeys = new java.util.concurrent.ConcurrentHashMap<>();
146	
147	    private final ClinicService clinicService;
148	
149	    private final OwnerMapper ownerMapper;
150	
151	    private final PetMapper petMapper;
152	
153	    private final VisitMapper visitMapper;
154	
155	    public OwnerRestControllerV1(ClinicService clinicService,
156	                                 OwnerMapper ownerMapper,
157	                                 PetMapper petMapper,
158	                                 VisitMapper visitMapper) {
159	        this.clinicService = clinicService;
160	        this.ownerMapper = ownerMapper;
161	        this.petMapper = petMapper;
162	        this.visitMapper = visitMapper;
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
168	        Collection<Owner> owners;
169	        if (lastName != null) {
170	            owners = this.clinicService.findOwnerByLastName(lastName);
171	        } else {
172	            owners = this.clinicService.findAllOwners();
173	        }
174	        if (owners.isEmpty()) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
178	    }
179	
180	    /**
181	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
182	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
183	     */
184	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
185	        List<String> missing = new ArrayList<>();
186	        if (isBlank(ownerFieldsDto.getFirstName())) {
187	            missing.add("firstName");
188	        }
189	        if (isBlank(ownerFieldsDto.getLastName())) {
190	            missing.add("lastName");
191	        }
192	        if (isBlank(ownerFieldsDto.getAddress())) {
193	            missing.add("address");
194	        }
195	        if (isBlank(ownerFieldsDto.getCity())) {
196	            missing.add("city");
197	        }
198	        if (isBlank(ownerFieldsDto.getTelephone())) {
199	            missing.add("telephone");
200	        }
201	        if (!missing.isEmpty()) {
202	            throw new RequiredFieldsMissingException(missing);
203	        }
204	    }
205	
206	    private static boolean isBlank(String value) {
207	        return value == null || value.isBlank();
208	    }
209	
210	    /**
211	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
212	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
213	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
214	     * normalized value is what gets stored, returned and used for every address comparison; a value
215	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
216	     * rejects it.
217	     *
218	     * @param address the raw address as supplied by the caller, may be {@code null}
219	     * @return the normalized address ({@code ""} when blank or {@code null})
220	     */
221	    private static String normalizeAddress(String address) {
222	        if (address == null) {
223	            return "";
224	        }
225	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
226	        if (collapsed.isEmpty()) {
227	            return "";
228	        }
229	        String[] tokens = collapsed.split(" ");
230	        StringBuilder sb = new StringBuilder(collapsed.length());
231	        for (int i = 0; i < tokens.length; i++) {
232	            String token = tokens[i];
233	            switch (token) {
234	                case "ST" -> token = "STREET";
235	                case "RD" -> token = "ROAD";
236	                case "AVE" -> token = "AVENUE";
237	                default -> { }
238	            }
239	            if (i > 0) {
240	                sb.append(' ');
241	            }
242	            sb.append(token);
243	        }
244	        return sb.toString();
245	    }
246	
247	    /**
248	     * Resolves and normalizes the owner's address on create, supporting both the structured form
249	     * ({@code addressLine1} / {@code addressLine2}) and the flat {@code address} form kept for
250	     * backward compatibility. Whichever address fields are supplied are normalized (see
251	     * {@link #normalizeAddress(String)}). The structured form is preferred when present: when
252	     * {@code addressLine1} is non-blank the composed {@code address} is the normalized
253	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
254	     * {@code addressLine2} is present; otherwise the composed {@code address} is the normalized flat
255	     * {@code address}. The normalized structured fields are written back so they are stored and
256	     * returned, and the composed value is written to {@code address} so everything that reads the
257	     * address (the household hash, postcode validation and locality) uses the structured fields when
258	     * present, falling back to the flat address. When neither form supplies an address the composed
259	     * {@code address} is blank, so the required-field check rejects it.
260	     *
261	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
262	     */
263	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
264	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
265	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
266	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
267	        String composed;
268	        if (!line1.isEmpty()) {
269	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
270	        } else {
271	            composed = flat;
272	        }
273	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
274	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
275	        ownerFieldsDto.setAddress(composed);
276	    }
277	
278	    /**
279	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
280	     * A leading {@code +} and its country code are kept as given; otherwise the country code
281	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
282	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
283	     * is recognized the national number must have the exact length that code requires ({@code +61}
284	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
285	     * returned.
286	     *
287	     * @param telephone the raw telephone as supplied by the caller
288	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
289	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
290	     *     national-number length is wrong for its country code
291	     */
292	    private static String normalizeTelephone(String telephone) {
293	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
294	        String e164;
295	        if (cleaned.startsWith("+")) {
296	            e164 = "+" + cleaned.substring(1);
297	        } else {
298	            String national = cleaned;
299	            if (national.startsWith("0")) {
300	                national = national.substring(1);
301	            }
302	            e164 = "+61" + national;
303	        }
304	        String digits = e164.substring(1);
305	        if (!digits.matches("\\d{8,15}")) {
306	            throw new InvalidTelephoneException(
307	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
308	        }
309	        if (digits.startsWith("61")) {
310	            requireNationalLength(digits.substring(2), 9, "+61");
311	        } else if (digits.startsWith("1")) {
312	            requireNationalLength(digits.substring(1), 10, "+1");
313	        }
314	        return e164;
315	    }
316	
317	    /**
318	     * Enforces that the national portion of an E.164 number has the exact number of digits its
319	     * country code requires.
320	     *
321	     * @param national the national-number digits (the part after the country code)
322	     * @param expected the exact national-number length the country code requires
323	     * @param countryCode the country code, for the error message
324	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
325	     */
326	    private static void requireNationalLength(String national, int expected, String countryCode) {
327	        if (national.length() != expected) {
328	            throw new InvalidTelephoneException(
329	                "Telephone with country code '" + countryCode + "' must have " + expected
330	                    + " national digits");
331	        }
332	    }
333	
334	    /**
335	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
336	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
337	     *
338	     * @param email the raw email as supplied by the caller, may be {@code null}
339	     * @return the lower-cased email, or {@code null} when none was supplied
340	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
341	     */
342	    private static String normalizeEmail(String email) {
343	        if (email == null || email.isBlank()) {
344	            return null;
345	        }
346	        String trimmed = email.trim();
347	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
348	            throw new InvalidEmailException("Email must be a syntactically valid address");
349	        }
350	        String lowerCased = trimmed.toLowerCase(Locale.ROOT);
351	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
352	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
353	            throw new InvalidEmailException("Email domain is not allowed");
354	        }
355	        return lowerCased;
356	    }
357	
358	    /**
359	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
360	     * email and household checks. The key is the lower-case hex SHA-256 of
361	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, with an empty segment
362	     * for an absent telephone or email. Because the telephone is part of the key, two owners that
363	     * differ in any one segment (for example two members of the same household with different
364	     * telephones) produce different keys and are therefore not hard duplicates.
365	     *
366	     * @param normalizedTelephone the E.164 telephone of the owner
367	     * @param email the lower-cased email of the owner, may be {@code null}
368	     * @param lastName the last name of the owner, reduced to its Soundex code, may be {@code null}
369	     * @return the derived identity key
370	     */
371	    private static String deriveIdentityKey(String normalizedTelephone, String email, String lastName) {
372	        return org.springframework.samples.petclinic.util.IdentityKeys.identityKey(
373	            normalizedTelephone, email, lastName);
374	    }
375	
376	    /**
377	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
378	     * owner. This one check replaces the former separate telephone, email and household duplicate
379	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
380	     * segment are both allowed. Each existing owner's key is derived from its stored, already
381	     * normalized telephone, email and household identifier.
382	     *
383	     * @param identityKey the derived identity key of the owner being created
384	     * @throws DuplicateIdentityException if another owner already has this identity key
385	     */
386	    /**
387	     * The existing owners considered by the create endpoint's duplicate and identity checks:
388	     * every owner that is not soft-deleted. A soft-deleted owner retains its row but is ignored
389	     * here, so a create that would otherwise be blocked by it is allowed.
390	     *
391	     * @return a stream of the owners not flagged deleted
392	     */
393	    private java.util.stream.Stream<Owner> activeOwners() {
394	        return this.clinicService.findAllOwners().stream()
395	            .filter(existing -> !existing.isDeleted());
396	    }
