398	    private void rejectDuplicateIdentity(String identityKey) {
399	        boolean inUse = activeOwners()
400	            .anyMatch(existing -> identityKey.equals(
401	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())));
402	        if (inUse) {
403	            throw new DuplicateIdentityException(
404	                "An owner with the same identity key already exists");
405	        }
406	    }
