408	    /**
409	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
410	     * not a hard identity duplicate (its {@code identityKey} differs) but shares the phonetic code of
411	     * this owner's last name (its Soundex) and its postcode. Because the telephone is part of the
412	     * identity key, two owners with the same surname and postcode but different telephones are no
413	     * longer hard duplicates — they surface here as a soft match instead. When the postcode is absent
414	     * no owner can share it, so there is never a match. When several existing owners qualify the one
415	     * with the lowest id is returned, so the result is deterministic.
416	     *
417	     * @param lastName the last name of the owner being created
418	     * @param postcode the postcode of the owner being created, may be {@code null}
419	     * @param identityKey the derived identity key of the owner being created
420	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
421	     */
422	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String identityKey) {
423	        if (postcode == null || postcode.isBlank()) {
424	            return null;
425	        }
426	        String soundex = org.springframework.samples.petclinic.util.IdentityKeys.soundex(lastName);
427	        return activeOwners()
428	            .filter(existing -> soundex.equals(
429	                org.springframework.samples.petclinic.util.IdentityKeys.soundex(existing.getLastName())))
430	            .filter(existing -> postcode.equals(existing.getPostcode()))
431	            .filter(existing -> !identityKey.equals(
432	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())))
433	            .map(Owner::getId)
434	            .filter(java.util.Objects::nonNull)
435	            .min(Integer::compareTo)
436	            .orElse(null);
437	    }
