447	     * @param lastName the last name of the owner being created
448	     * @param postcode the postcode of the owner being created, may be {@code null}
449	     * @return the stable household identifier
450	     */
451	    private static String householdId(String lastName, String postcode) {
452	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
453	        return sha256HexPrefix(key, 12);
454	    }
