558	    /** Fixed public holidays the business-day roll skips. */
559	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
560	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
561	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
562	        LocalDate.parse("2026-12-28"));
