564	    /**
565	     * Rolls a registration date forward to a business day: any date landing on a Saturday, Sunday or
566	     * listed public holiday is advanced one day at a time until it reaches the next non-holiday
567	     * weekday, and any other weekday is returned unchanged.
568	     *
569	     * @param date the effective registration date, supplied or defaulted to the server date
570	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
571	     */
572	    private static LocalDate toBusinessDay(LocalDate date) {
573	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
574	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
575	                || PUBLIC_HOLIDAYS.contains(date)) {
576	            date = date.plusDays(1);
577	        }
578	        return date;
579	    }
