581	    /**
582	     * Builds the unified member id assigned to an owner on create, formatted
583	     * {@code '<REGION><FY><HASH8><CHK>'}. {@code REGION} is the region code derived from the owner's
584	     * postcode (the region whose inclusive range contains the postcode, or {@code 'UNKNOWN'} when the
585	     * postcode is absent or in no known range). {@code FY} is the 2-digit fiscal year (the last two
586	     * digits of the calendar year in which the fiscal year of the business-day-adjusted
587	     * registrationDate ends; the fiscal year starts on 1 July). {@code HASH8} is the first eight
588	     * upper-cased hex characters of the SHA-256 of {@code normalizedTelephone + lastName} (the same
589	     * hash used by the region-and-hash identity). {@code CHK} is a single Luhn check digit computed
590	     * over the digits of {@code '<REGION><FY><HASH8>'}, e.g. {@code 'NSW261A2B3C4D5'}.
591	     *
592	     * @param postcode the postcode of the owner being created, may be {@code null}
593	     * @param registrationDate the business-day-adjusted registration date of the owner being created
594	     * @param normalizedTelephone the E.164 telephone of the owner being created
595	     * @param lastName the last name of the owner being created
596	     * @return the formatted member id
597	     */
598	    private String memberId(String postcode, LocalDate registrationDate, String normalizedTelephone, String lastName) {
599	        String region = regionFromPostcode(postcode);
600	        String fiscalYear = String.format("%02d", fiscalYearEnding(registrationDate) % 100);
601	        String hash8 = sha256HexPrefix(normalizedTelephone + lastName, 8);
602	        String base = region + fiscalYear + hash8;
603	        return base + luhnCheckDigit(base);
604	    }
605	
606	    /**
607	     * The fiscal year in which a date falls, labelled by the calendar year in which the fiscal year
608	     * ends. The fiscal year starts on 1 July, so a date on or after 1 July belongs to the fiscal year
609	     * ending the following calendar year, and a date before 1 July belongs to the fiscal year ending
610	     * that calendar year.
611	     */
612	    private static int fiscalYearEnding(LocalDate date) {
613	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
614	    }
615	
616	    /**
617	     * The Luhn check digit (0-9) computed over the digits contained in {@code value}; non-digit
618	     * characters are ignored.
619	     */
620	    private static int luhnCheckDigit(String value) {
621	        int sum = 0;
622	        boolean dbl = true;
623	        for (int i = value.length() - 1; i >= 0; i--) {
624	            char c = value.charAt(i);
625	            if (c < '0' || c > '9') {
626	                continue;
627	            }
628	            int d = c - '0';
629	            if (dbl) {
630	                d *= 2;
631	                if (d > 9) {
632	                    d -= 9;
633	                }
634	            }
635	            sum += d;
636	            dbl = !dbl;
637	        }
638	        return (10 - (sum % 10)) % 10;
639	    }
