652	    /**
653	     * De-duplicates a freshly computed member id against the member ids already held by existing
654	     * owners. When the id is unused it is returned unchanged; otherwise {@code '-<n>'} is appended
655	     * with the smallest {@code n} of 2 or more that yields an id no existing owner carries.
656	     *
657	     * @param memberId the computed member id for the owner being created
658	     * @return the same id when unique, otherwise the id with a {@code '-<n>'} suffix that makes it
659	     *     unique
660	     */
661	    private String deduplicateMemberId(String memberId) {
662	        Set<String> existing = new java.util.HashSet<>();
663	        for (Owner owner : this.clinicService.findAllOwners()) {
664	            if (owner.getMemberId() != null) {
665	                existing.add(owner.getMemberId());
666	            }
667	        }
668	        if (!existing.contains(memberId)) {
669	            return memberId;
670	        }
671	        int n = 2;
672	        while (existing.contains(memberId + "-" + n)) {
673	            n++;
674	        }
675	        return memberId + "-" + n;
676	    }
