678	    /**
679	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
680	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
681	     * {@code null}, non-numeric, or in no known range.
682	     *
683	     * @param postcode the postcode, may be {@code null}
684	     * @return the region code, or {@code 'UNKNOWN'}
685	     */
686	    private static String regionFromPostcode(String postcode) {
687	        if (postcode == null || postcode.isBlank()) {
688	            return "UNKNOWN";
689	        }
690	        int code;
691	        try {
692	            code = Integer.parseInt(postcode.trim());
693	        } catch (NumberFormatException e) {
694	            return "UNKNOWN";
695	        }
696	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
697	            int[] range = entry.getValue();
698	            if (code >= range[0] && code <= range[1]) {
699	                return entry.getKey();
700	            }
701	        }
702	        return "UNKNOWN";
703	    }
