705	    /**
706	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
707	     * upper-cased.
708	     *
709	     * @param value the string to hash
710	     * @param length the number of leading hex characters to return
711	     * @return the upper-cased hex prefix of the digest
712	     */
713	    private static String sha256HexPrefix(String value, int length) {
714	        try {
715	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
716	            StringBuilder sb = new StringBuilder(digest.length * 2);
717	            for (byte b : digest) {
718	                sb.append(String.format("%02x", b));
719	            }
720	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
721	        } catch (NoSuchAlgorithmException e) {
722	            throw new IllegalStateException("SHA-256 not available", e);
723	        }
724	    }
