745	    /**
746	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
747	     * number of existing owners already carrying the same {@code householdId}. The household
748	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
749	     * with that identifier) is a household of one. The count includes the owner being created (hence
750	     * the {@code + 1}).
751	     *
752	     * @param householdId the stable household identifier of the owner being created
753	     * @return the number of household members after this create (always at least 1)
754	     */
755	    private int householdSize(String householdId) {
756	        if (householdId == null) {
757	            return 1;
758	        }
759	        return (int) this.clinicService.findAllOwners().stream()
760	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
761	            .count() + 1;
762	    }
