764	    /**
765	     * Computes the household-capped membership level for the owner being created. The level starts as
766	     * the owner's own derived level (from its membership points). When at least one existing (active)
767	     * household member shares the owner's {@code householdId}, the level is capped so it may not exceed
768	     * one above the current maximum membership level among those existing members; with no existing
769	     * household member no cap applies and the derived level is returned unchanged. Returns {@code null}
770	     * when no level can be derived for the owner.
771	     *
772	     * @param owner the owner being created, with its level-affecting fields already populated
773	     * @param householdId the stable household identifier of the owner being created
774	     * @return the capped membership level, or {@code null} when none can be derived
775	     */
776	    private Integer cappedMembershipLevel(Owner owner, String householdId) {
777	        Integer level = ownerMapper.membershipLevel(owner);
778	        if (level == null || householdId == null) {
779	            return level;
780	        }
781	        java.util.OptionalInt maxExisting = activeOwners()
782	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
783	            .map(ownerMapper::membershipLevel)
784	            .filter(java.util.Objects::nonNull)
785	            .mapToInt(Integer::intValue)
786	            .max();
787	        if (maxExisting.isPresent()) {
788	            level = Math.min(level, maxExisting.getAsInt() + 1);
789	        }
790	        return level;
791	    }
