793	    /**
794	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
795	     * lower-casing.
796	     *
797	     * @param value the raw name, may be {@code null}
798	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
799	     */
800	    private static String normalizeName(String value) {
801	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
