804	    /**
805	     * The fixed city-to-region table used to validate a postcode against its city
806	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
807	     * therefore accepts any 4-digit postcode.
808	     */
809	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
810	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
811	
812	    /**
813	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
814	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
815	     */
816	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
817	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
818	
819	    /**
820	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
821	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
822	     * when the city maps to a known region, must fall within that region's inclusive range
823	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
824	     * postcode.
825	     *
826	     * @param city the city of the owner being created
827	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
828	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
829	     *     for the city's region
830	     */
831	    private static void validatePostcode(String city, String postcode) {
832	        if (postcode == null || postcode.isBlank()) {
833	            return;
834	        }
835	        if (!postcode.matches("\\d{4}")) {
836	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
837	        }
838	        String region = CITY_REGION.get(city);
839	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
840	        if (range != null) {
841	            int value = Integer.parseInt(postcode);
842	            if (value < range[0] || value > range[1]) {
843	                throw new InvalidPostcodeException(
844	                    "Postcode is out of range for the city's region");
845	            }
846	        }
847	    }
