860	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, if any. The
861	     * header is absent for ordinary creates; when present and non-blank it enables the idempotent-create
862	     * behaviour keyed on its value.
863	     *
864	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
865	     */
866	    private static String currentIdempotencyKey() {
867	        var attributes = org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
868	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
869	            return null;
