876	    @Override
877	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
878	        String idempotencyKey = currentIdempotencyKey();
879	        if (idempotencyKey != null) {
880	            Integer existingId = idempotencyKeys.get(idempotencyKey);
881	            if (existingId != null) {
882	                Owner existing = this.clinicService.findOwnerById(existingId);
883	                if (existing != null) {
884	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
885	                }
886	            }
887	        }
888	        applyAddress(ownerFieldsDto);
889	        validateRequiredFields(ownerFieldsDto);
890	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
891	        if (registrationDate == null) {
892	            registrationDate = LocalDate.now();
893	        } else if (registrationDate.isAfter(LocalDate.now())) {
894	            throw new FutureRegistrationDateException(
895	                "registrationDate must not be later than the server date");
896	        }
897	        registrationDate = toBusinessDay(registrationDate);
898	        ownerFieldsDto.setRegistrationDate(registrationDate);
899	        rejectDailyOwnerLimit(registrationDate);
900	        rejectCityAtCapacity(ownerFieldsDto.getCity());
901	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
902	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
903	        ownerFieldsDto.setTelephone(normalizedTelephone);
904	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
905	        ownerFieldsDto.setEmail(normalizedEmail);
906	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
907	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
908	        String identityKey = deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerFieldsDto.getLastName());
909	        rejectDuplicateIdentity(identityKey);
910	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
911	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), identityKey);
912	        HttpHeaders headers = new HttpHeaders();
913	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
914	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
915	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
916	        owner.setMemberId(deduplicateMemberId(memberId(
917	            ownerFieldsDto.getPostcode(), registrationDate, normalizedTelephone, ownerFieldsDto.getLastName())));
918	        owner.setHouseholdId(ownerHouseholdId);
919	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
920	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
921	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
922	        owner.setCapacityWarning(capacityWarning(ownerFieldsDto.getCity()));
923	        owner.setMembershipLevel(cappedMembershipLevel(owner, ownerHouseholdId));
924	        this.clinicService.saveOwner(owner);
925	        if (idempotencyKey != null) {
926	            idempotencyKeys.put(idempotencyKey, owner.getId());
927	        }
928	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
929	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
930	            ownerMapper.membershipLevel(owner));
931	        AUDIT.info(new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
932	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner)).toJson());
933	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
934	        headers.setLocation(UriComponentsBuilder.newInstance()
935	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
936	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
937	    }
938	
939	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
940	    @Override
941	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
942	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
943	        if (currentOwner == null) {
944	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
945	        }
946	        currentOwner.setAddress(ownerFieldsDto.getAddress());
947	        currentOwner.setCity(ownerFieldsDto.getCity());
948	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
949	        currentOwner.setLastName(ownerFieldsDto.getLastName());
950	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
951	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
